p='people/people.ts'
s=open(p).read()
s=s.replace("""// The sheet's ledger is the grand total of everyone's scaled, leaving out anyone whose scaled is "n/a".
""","""// The sheet's ledger is the grand total of everyone's scaled, leaving out anyone whose scaled is "n/a",
