    this.people().reduce((total, p) => total + (p.scaled ?? 0), 0),
  );""","""  private readonly scaledTotal = computed(() =>
    this.people().reduce((total, p) => total + (p.scaled ?? 0), 0),
  );
  protected readonly ledger = computed(() => {
    const order = this.scaledOrder();
    return this.scaledTotal() - (order.length > 0 ? order[0].scaled! : 0);
  });""")
