    return Math.floor(order.reduce((sum, p) => sum + p.scaled!, 0) / order.length);""","""    if (order.length === 0) return null;
    return Math.floor(this.ledger() / this.headcount());""")
s=s.replace("""  protected readonly concentration = computed(() => {
    const total = this.ledger();""","""  protected readonly concentration = computed(() => {
    const total = this.scaledTotal();""")
open(p,'w').write(s)
